describe('Delete Account Feature', () => {
  beforeEach(() => {
    cy.visit('/account-settings');
    cy.login('testuser@example.com', 'password123');
  });

  it('should successfully delete account with correct password confirmation', () => {
    cy.get('[data-testid="delete-account-btn"]').click();

    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
    cy.get('[data-testid="delete-confirmation-text"]').should('contain', 'Are you sure you want to delete your account?');

    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="success-message"]').should('contain', 'Account deleted successfully');
    cy.url().should('include', '/');
    cy.get('[data-testid="login-btn"]').should('be.visible');
  });

  it('should show error when incorrect password is provided', () => {
    cy.get('[data-testid="delete-account-btn"]').click();

    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="error-message"]').should('contain', 'Incorrect password');
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');
  });

  it('should close modal when cancel button is clicked', () => {
    cy.get('[data-testid="delete-account-btn"]').click();
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');

    cy.get('[data-testid="cancel-btn"]').click();
    cy.get('[data-testid="delete-account-modal"]').should('not.be.visible');
  });

  it('should require password field to be filled before submission', () => {
    cy.get('[data-testid="delete-account-btn"]').click();
    cy.get('[data-testid="delete-account-modal"]').should('be.visible');

    cy.get('[data-testid="confirm-delete-btn"]').should('be.disabled');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="confirm-delete-btn"]').should('not.be.disabled');
  });
});
